insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A educação para o trânsito é direito de todos e dever prioritário dos componentes do Sistema Nacional de Trânsito. É obrigatória a existência de coordenação educacional em cada órgão ou entidade do Sistema, e os órgãos executivos devem promover o funcionamento de Escolas Públicas de Trânsito, nos moldes do Contran.', '["Direito de todos.","Coordenação educacional obrigatória.","Escolas Públicas de Trânsito."]'::jsonb, '["Dever PRIORITÁRIO do sistema."]'::jsonb, 'O Detran mantém a Escola Pública de Trânsito.', '["Assertiva que torna facultativa a coordenação educacional nos órgãos do sistema erra."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-74' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ba5242e437449d38e8763b73fac84a26f2a7545674a93fab5199b221a5c4be94'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran estabelece, anualmente, os temas e cronogramas das campanhas de âmbito nacional promovidas por todos os órgãos do Sistema, em especial nas férias escolares, feriados prolongados e na Semana Nacional de Trânsito. Os órgãos promovem outras campanhas em sua circunscrição, de caráter permanente, e os serviços de rádio e difusão de sons e imagens explorados pelo poder público são obrigados a difundi-las gratuitamente.', '["Campanhas nacionais definidas anualmente pelo Contran.","Campanhas locais.","Caráter permanente e difusão gratuita pelo poder público."]'::jsonb, '["Quem fixa os temas nacionais é o Contran."]'::jsonb, 'A campanha do feriado prolongado segue o tema fixado pelo Contran.', '["Assertiva que atribui ao Detran a fixação dos temas nacionais erra: é do Contran."]'::jsonb, '[]'::jsonb, '["Art. 76"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-75' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4d942d35608fe11940504d1a0f9f9b3e4378099f46592b8e6aadd3472f2eb409'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A educação para o trânsito é promovida na pré-escola e nas escolas de 1º, 2º e 3º graus, com planejamento e ações coordenadas entre os órgãos de trânsito e de educação da União, dos Estados, do Distrito Federal e dos Municípios. O Ministério da Educação, mediante proposta do Contran e do Conselho de Reitores, promove a adoção de um currículo interdisciplinar sobre segurança de trânsito, a adaptação de conteúdos e a criação de corpos técnicos e cursos de especialização.', '["Educação em todos os níveis de ensino.","Coordenação entre trânsito e educação.","Currículo interdisciplinar proposto com o Contran."]'::jsonb, '["Texto usa a nomenclatura antiga dos graus de ensino."]'::jsonb, 'A escola inclui conteúdo de segurança no trânsito no currículo.', '["Assertiva que restringe a educação para o trânsito ao ensino superior erra."]'::jsonb, '[]'::jsonb, '["Art. 74"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-76' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'fe953125db8538e6687acfb187096eb1679fedc9a55191bf90ddf6520e8d1930'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No âmbito da educação para o trânsito, cabe ao Ministério da Saúde, mediante proposta do Contran, estabelecer campanha nacional para esclarecer condutas a serem seguidas nos primeiros socorros em caso de sinistros. As campanhas têm caráter permanente por intermédio do SUS, intensificadas nos períodos do art. 76.', '["Campanha nacional de primeiros socorros.","Caráter permanente pelo SUS."]'::jsonb, '["Competência do Ministério da Saúde, com proposta do Contran."]'::jsonb, 'Campanha orienta o que fazer até a chegada do socorro.', '["Assertiva que atribui ao Ministério dos Transportes a campanha de primeiros socorros erra."]'::jsonb, '[]'::jsonb, '["Art. 76"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-77' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '73b68df62542fc547b5c371f5ca1feee207a410acde84096ef40d953b8e682d8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São assegurados aos órgãos do Sistema Nacional de Trânsito os mecanismos dos arts. 77-B a 77-E para a veiculação de mensagens educativas de trânsito em todo o território nacional, em caráter suplementar às campanhas dos arts. 75 e 77.', '["Mecanismos suplementares de mensagens educativas."]'::jsonb, '["Suplementar às campanhas oficiais."]'::jsonb, 'A publicidade de veículos traz mensagem educativa.', '["Assertiva que torna os mecanismos substitutivos das campanhas oficiais erra: são suplementares."]'::jsonb, '[]'::jsonb, '["Art. 77-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-77-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'fa36a4de72072b66384564157197123a3e6b1c8f2ed407911dd130142fb03047'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Toda peça publicitária destinada à divulgação ou promoção, nos meios de comunicação social, de produto da indústria automobilística ou afim deve incluir obrigatoriamente mensagem educativa de trânsito conjuntamente veiculada. Consideram-se produtos os veículos rodoviários automotores de qualquer espécie e seus componentes, peças e acessórios. A obrigação se aplica à propaganda comercial de qualquer natureza.', '["Mensagem educativa obrigatória na publicidade automotiva.","Veículos, peças e acessórios."]'::jsonb, '["Obrigatória em toda peça publicitária do setor."]'::jsonb, 'O comercial de carro termina com mensagem educativa de trânsito.', '["Assertiva que dispensa a mensagem educativa na publicidade de peças e acessórios erra."]'::jsonb, '[]'::jsonb, '["Art. 77-E"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-77-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c85affe0120a62c370199fdc7b07a713108a9543e66311fbe0fb599b862b4b41'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando se tratar de publicidade em outdoor instalado à margem de rodovia, dentro ou fora da faixa de domínio, a obrigação do art. 77-B estende-se à propaganda de qualquer tipo de produto e anunciante, inclusive institucional ou eleitoral.', '["Outdoor à margem de rodovia.","Vale para qualquer produto, inclusive institucional e eleitoral."]'::jsonb, '["Abrange até a propaganda eleitoral."]'::jsonb, 'O outdoor de qualquer anunciante na beira da rodovia traz a mensagem de trânsito.', '["Assertiva que restringe a obrigação a anúncios de veículos nos outdoors de rodovia erra."]'::jsonb, '[]'::jsonb, '["Art. 77-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-77-c' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '791881459a3ae2228e0641f4b472e647f8f898df327a96f45016aaeb996d29c1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran especifica o conteúdo e o padrão de apresentação das mensagens educativas, bem como os procedimentos de sua veiculação, em conformidade com as diretrizes das campanhas educativas de trânsito do art. 75.', '["Contran define conteúdo, padrão e procedimentos."]'::jsonb, '["Competência do Contran."]'::jsonb, 'O Contran estabelece o formato da mensagem nas propagandas.', '["Assertiva que atribui a cada anunciante a definição do conteúdo da mensagem erra."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-77-d' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a6a66d41464cb63300ed80391ae51b55a4fb3340a9630bca9150826b3eea5491'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A veiculação de publicidade em desacordo com as condições dos arts. 77-A a 77-D é infração punível com advertência por escrito, suspensão de qualquer outra propaganda do produto nos veículos de divulgação por até sessenta dias e multa de R$ 1.627,00 a R$ 8.135,00, cobrada do dobro até o quíntuplo em caso de reincidência. As sanções são aplicadas isolada ou cumulativamente, e qualquer infração acarreta a imediata suspensão da veiculação da peça até o cumprimento das exigências.', '["Advertência por escrito.","Suspensão da propaganda por até sessenta dias.","Multa de R$ 1.627,00 a R$ 8.135,00.","Sanções isoladas ou cumulativas."]'::jsonb, '["Multa do dobro ao quíntuplo na reincidência.","Valores em reais fixados no texto legal; confira eventual atualização."]'::jsonb, 'A emissora exibe propaganda sem mensagem e a peça é suspensa até a regularização.', '["Assertiva que impede a cumulação das sanções erra: podem ser aplicadas cumulativamente."]'::jsonb, '[]'::jsonb, '["Art. 77-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-77-e' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8d428d3f0e462b7a1dc1f44b7552c6d2473309f6f45e8cdfa252a7859a931ef9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os Ministérios da Saúde, da Educação, do Trabalho e Emprego, dos Transportes e da Justiça e Segurança Pública, por intermédio do Contran, desenvolvem e implementam programas destinados à prevenção de sinistros. É repassado mensalmente ao Coordenador do Sistema Nacional de Trânsito o montante equivalente a até 5% do total dos valores arrecadados destinados à Seguridade Social dos prêmios do seguro obrigatório, para aplicação nos programas e na divulgação.', '["Programas de prevenção de sinistros.","Repasse mensal de até 5% da arrecadação do seguro obrigatório."]'::jsonb, '["ATUALIZAÇÃO: a redação do parágrafo único mudou conforme a legislação do seguro obrigatório; confira o texto vigente.","Repasse de até 5%."]'::jsonb, 'Parte da arrecadação do seguro financia campanhas de prevenção.', '["Assertiva que fixa em 10% o repasse erra: são até 5%."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-78' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3124cd6d36e31eea06ab85935801c941b3c88ab90c4ed12e542bfb943ea5bc5c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos e entidades executivos de trânsito podem firmar convênio com os órgãos de educação da União, dos Estados, do Distrito Federal e dos Municípios, objetivando o cumprimento das obrigações do capítulo sobre educação para o trânsito.', '["Convênio com órgãos de educação."]'::jsonb, '["Faculdade, por meio de convênio."]'::jsonb, 'O Detran firma convênio com a secretaria de educação.', '["Assertiva que torna obrigatório o convênio com os órgãos de educação erra."]'::jsonb, '[]'::jsonb, '["Art. 76"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-79' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '753365a595bebb770af6bb8fac2cb4dcf87620ba3b450b6b589652cd365ca029'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sempre que necessário, é colocada ao longo da via a sinalização prevista no Código e em legislação complementar, destinada a condutores e pedestres, vedada a utilização de qualquer outra. A sinalização deve ficar em posição e condições que a tornem perfeitamente visível e legível, de dia e de noite, em distância compatível com a segurança, conforme normas do Contran. O órgão máximo executivo de trânsito da União pode autorizar, em caráter experimental e por período prefixado, sinalização e equipamentos não previstos no Código.', '["Só a sinalização prevista em lei.","Visível e legível de dia e de noite.","Uso experimental autorizado pelo órgão máximo executivo da União."]'::jsonb, '["Vedada outra sinalização não prevista."]'::jsonb, 'Placa não prevista só é usada em caráter experimental autorizado.', '["Assertiva que permite qualquer sinalização à escolha do município erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-80' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '691b45676d9784207d05c6b7b100ae634f79c1e5c9dd69631f17637c537a2bf4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas vias públicas e nos imóveis é proibido colocar luzes, publicidade, inscrições, vegetação e mobiliário que possam gerar confusão, interferir na visibilidade da sinalização e comprometer a segurança do trânsito.', '["Proibição de elementos que confundam ou prejudiquem a sinalização."]'::jsonb, '["Alcança vias públicas E imóveis."]'::jsonb, 'Árvore que esconde a placa de pare fere a regra.', '["Assertiva que restringe a proibição às vias públicas erra: alcança também imóveis."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-81' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '46895099c0fad60c9f8a8b5d428bb146f35004f3bc613d2d7d986f97be19d8c9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É proibido afixar sobre a sinalização de trânsito e respectivos suportes, ou junto a ambos, qualquer tipo de publicidade, inscrições, legendas e símbolos que não se relacionem com a mensagem da sinalização.', '["Proibida publicidade na sinalização e em seus suportes."]'::jsonb, '["Vale para os suportes também."]'::jsonb, 'Colar anúncio no poste da placa de trânsito é proibido.', '["Assertiva que permite publicidade nos suportes das placas erra."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-82' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '930052e9a0d49f7d593cb30a3b7f4591ba4f68b8c432a1642cdc4c576c901f99'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A afixação de publicidade ou de quaisquer legendas ou símbolos ao longo das vias condiciona-se à prévia aprovação do órgão ou entidade com circunscrição sobre a via.', '["Prévia aprovação do órgão com circunscrição."]'::jsonb, '["Aprovação PRÉVIA."]'::jsonb, 'O anunciante pede aprovação antes de instalar o painel à margem da via.', '["Assertiva que dispensa a aprovação prévia da publicidade ao longo das vias erra."]'::jsonb, '[]'::jsonb, '["Art. 82"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-83' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd7ca8ada99942e7dac4b3f395a3be3d38ff9c44843d2e9ee2e2ce99dd7e81db7'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
