insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os locais destinados a postos de gasolina, oficinas, estacionamentos ou garagens de uso coletivo devem ter suas entradas e saídas devidamente identificadas, na forma regulamentada pelo Contran.', '["Identificação de entradas e saídas.","Forma regulamentada pelo Contran."]'::jsonb, '["Regra do Contran."]'::jsonb, 'O posto sinaliza claramente onde entram e saem os veículos.', '["Assertiva que dispensa a identificação das entradas de estacionamentos coletivos erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-86' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3e2a2fb0c625337d40ec31299546103579c6cfcf42891c86d685d99949180680'
