insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As vagas de estacionamento regulamentado de que trata o inciso XVII do art. 181 (vagas para idosos e pessoas com deficiência) devem ser sinalizadas com as respectivas placas indicativas de destinação e com placas informando os dados sobre a infração por estacionamento indevido.', '["Vagas especiais sinalizadas.","Placas informando a infração por uso indevido."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'A vaga para idoso traz placa com a informação da multa.', '["Assertiva que dispensa a placa informativa sobre a infração nas vagas especiais erra."]'::jsonb, '[]'::jsonb, '["Art. 181"]'::jsonb, 'under_review', 'claude'
