insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma via pavimentada pode ser entregue após sua construção, ou reaberta ao trânsito após obras ou manutenção, enquanto não estiver devidamente sinalizada, vertical e horizontalmente, de forma a garantir condições adequadas de segurança. Nas vias ou trechos em obras deve ser afixada sinalização específica e adequada.', '["Sinalização vertical e horizontal antes da entrega.","Sinalização específica em obras."]'::jsonb, '["Sem sinalização, a via não pode ser aberta."]'::jsonb, 'A via recapeada só é liberada após a pintura das faixas.', '["Assertiva que permite abrir a via ao trânsito antes de sinalizá-la erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-88' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '312fba9b3999a4e0cf5e4754f9be15ac181be76bd3bf18f1e099ca940169d2cf'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
