and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran estabelece as normas e regulamentos a serem adotados em todo o território nacional na implementação das soluções da Engenharia de Tráfego, assim como os padrões a serem praticados por todos os órgãos e entidades do Sistema Nacional de Trânsito.', '["Normas nacionais de engenharia de tráfego.","Padrões para todos os órgãos."]'::jsonb, '["Padronização nacional pelo Contran."]'::jsonb, 'A mesma regra de projeto de sinalização vale em todo o país.', '["Assertiva que deixa a engenharia de tráfego sem padronização nacional erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-91' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8733eb2d299805808acfe88216d0665ea75033c3b46343a37bacb0650a861394'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum projeto de edificação que possa transformar-se em polo atrativo de trânsito pode ser aprovado sem prévia anuência do órgão ou entidade com circunscrição sobre a via e sem que do projeto conste área para estacionamento e indicação das vias de acesso adequadas.', '["Anuência prévia do órgão de trânsito.","Área de estacionamento e vias de acesso."]'::jsonb, '["Polo atrativo de trânsito exige anuência prévia."]'::jsonb, 'Um shopping só é aprovado com estacionamento e acessos adequados.', '["Assertiva que dispensa área de estacionamento no projeto de polos atrativos erra."]'::jsonb, '[]'::jsonb, '["Art. 95"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-93' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '016bd21d434f5b1c66c89413eeae0e0986048947573bdd67bbf328c4423b6ada'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Qualquer obstáculo à livre circulação e à segurança de veículos e pedestres, na via ou na calçada, que não possa ser retirado, deve ser devida e imediatamente sinalizado. É proibida a utilização de ondulações transversais e de sonorizadores como redutores de velocidade, salvo casos especiais definidos pelo órgão competente, nos padrões do Contran.', '["Obstáculo não removível deve ser sinalizado.","Ondulações e sonorizadores só em casos especiais."]'::jsonb, '["Lombada só nos casos e padrões definidos pelo Contran."]'::jsonb, 'A lombada segue o padrão definido pelo Contran.', '["Assertiva que permite instalar lombadas sem padrão do Contran erra."]'::jsonb, '[]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-94' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '279d00b713566d824c2cf09b157bb63c1f9d07d96f6140a98f16b763296a2250'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma obra ou evento que possa perturbar ou interromper a livre circulação de veículos e pedestres, ou colocar em risco sua segurança, pode ser iniciada sem permissão prévia do órgão de trânsito com circunscrição sobre a via. A obrigação de sinalizar é do responsável pela execução ou manutenção da obra ou do evento. Salvo emergência, a autoridade avisa a comunidade pelos meios de comunicação com quarenta e oito horas de antecedência de qualquer interdição da via, indicando caminhos alternativos.', '["Permissão prévia para obras e eventos.","Sinalização a cargo do responsável.","Aviso à comunidade com quarenta e oito horas de antecedência."]'::jsonb, '["Aviso com quarenta e oito horas de antecedência, salvo emergência."]'::jsonb, 'A interdição programada é anunciada com dois dias de antecedência.', '["Assertiva que dispensa o aviso prévio nas interdições programadas erra."]'::jsonb, '[]'::jsonb, '["Art. 93"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-95' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'dcb8817ccf837eaa7b1bacab8e556b1a0dfa4f91e24420d4b7daef953e30fe28'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos classificam-se quanto à tração em automotor, de propulsão humana, de tração animal e reboque ou semirreboque; e quanto à espécie em veículos de passageiros (bicicleta, ciclomotor, motoneta, motocicleta, triciclo, quadriciclo, automóvel, micro-ônibus, ônibus, bonde, reboque, charrete), de carga, mistos, de competição e de tração, entre outras categorias, além de quanto à categoria.', '["Classificação por tração.","Classificação por espécie: passageiros, carga, misto, competição e tração.","Há também classificação por categoria."]'::jsonb, '["Consulte o texto integral para a lista completa por espécie e categoria."]'::jsonb, 'A motocicleta é veículo automotor da espécie passageiros.', '["Assertiva que inclui a carroça entre os veículos de passageiros erra: é de carga."]'::jsonb, '[]'::jsonb, '["Anexo I"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-96' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7681d607eb028303010d0f07d145df23f5dd55865748a1f7a50d1c882542007a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As características dos veículos, suas especificações básicas, configuração e condições essenciais para registro, licenciamento e circulação são estabelecidas pelo Contran, em função de suas aplicações.', '["Características e especificações definidas pelo Contran."]'::jsonb, '["Competência do Contran."]'::jsonb, 'O Contran define os requisitos para registro de um novo tipo de veículo.', '["Assertiva que atribui ao fabricante a definição das condições de registro erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-97' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'fd4e987774d7f3554080aabe34170a8b74cafc2c41367a81ae8cb4c5c7996ccc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum proprietário ou responsável pode, sem prévia autorização da autoridade competente, fazer ou ordenar modificações das características de fábrica do veículo. Os veículos e motores novos ou usados que sofrerem alterações ou conversões devem atender aos mesmos limites de emissão de poluentes e ruído, cabendo à entidade executora das modificações e ao proprietário a responsabilidade pelo cumprimento. Há regras específicas para a alteração de veículos do tipo utilitário jipe.', '["Modificações dependem de autorização prévia.","Atender aos limites de emissão e ruído.","Responsabilidade do executor e do proprietário."]'::jsonb, '["Alteração sem autorização é infração.","Responsabilidade do proprietário E da entidade executora."]'::jsonb, 'Trocar o motor do carro exige autorização e atendimento aos limites de emissão.', '["Assertiva que permite modificar o veículo sem autorização desde que seja para melhoria erra."]'::jsonb, '[]'::jsonb, '["Art. 230"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-98' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c98ab0a9f72f1813ad4a2462712fe61d7a59272484cf936e39573c7ed9683247'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
