insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Somente pode transitar pelas vias terrestres o veículo cujo peso e dimensões atendam aos limites estabelecidos pelo Contran. O excesso de peso é aferido por equipamento de pesagem ou pela verificação de documento fiscal. É tolerado um percentual sobre os limites de peso bruto total e por eixo, quando aferido por equipamento, e os equipamentos de pesagem são aferidos conforme metodologia e periodicidade do Contran.', '["Peso e dimensões conforme o Contran.","Aferição por equipamento ou documento fiscal.","Tolerância percentual."]'::jsonb, '["Tolerância percentual aplicada quando a aferição é por equipamento."]'::jsonb, 'O caminhão é pesado na balança da rodovia.', '["Assertiva que dispensa a aferição periódica dos equipamentos de pesagem erra."]'::jsonb, '[]'::jsonb, '["Art. 231"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-99' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '922a0c1afe7b74f256a76090527403ef588c231f8be5a36a463cc258790b739c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum veículo ou combinação de veículos pode transitar com lotação de passageiros, com peso bruto total ou com peso bruto total combinado com peso por eixo superior ao fixado pelo fabricante, nem ultrapassar a capacidade máxima de tração da unidade tratora. Os veículos de transporte coletivo de passageiros podem ter pneus extralargos, e o Contran regulamenta o uso nos demais. É permitida a fabricação de veículos de transporte de passageiros de até 15 m de comprimento na configuração de chassi 8x2.', '["Respeitar lotação e pesos do fabricante.","Capacidade máxima de tração.","Pneus extralargos.","Ônibus de até 15 m em chassi 8x2."]'::jsonb, '["ATUALIZAÇÃO: os parágrafos sobre pneus extralargos e chassi 8x2 vieram de leis posteriores."]'::jsonb, 'O ônibus não pode levar mais passageiros que a lotação fixada pelo fabricante.', '["Assertiva que permite exceder a lotação fixada pelo fabricante erra."]'::jsonb, '[]'::jsonb, '["Art. 99"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-100' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '19c26864dc7dd5238b24c38110fec13fa6800b603d8cb02600b5c4b90d35aad5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao veículo ou combinação de veículos de carga que não se enquadre nos limites de peso e dimensões do Contran pode ser concedida, pela autoridade com circunscrição sobre a via, autorização especial de trânsito, com prazo certo, válida para cada viagem ou por período, atendidas as medidas de segurança, conforme regulamentação do Contran. A autorização é concedida mediante requerimento que especifica as características do veículo e da carga, o percurso, a data e o horário do deslocamento.', '["Autorização especial de trânsito para cargas excedentes.","Prazo certo.","Requerimento com características, percurso e horário."]'::jsonb, '["A autorização não exime o beneficiário da responsabilidade por danos."]'::jsonb, 'A carga indivisível maior que o limite viaja com AET e escolta.', '["Assertiva que dispensa autorização para transportar carga acima dos limites erra."]'::jsonb, '[{"termo":"AET","significado":"Autorização especial de trânsito."}]'::jsonb, '["Art. 99"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-101' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '29961d623663515afd84db306e1e74335f6239449f94195c4e1fff99919cddfc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O veículo de carga deve estar devidamente equipado quando transitar, de modo a evitar o derramamento da carga sobre a via. O Contran fixa os requisitos mínimos e a forma de proteção das cargas, de acordo com a sua natureza.', '["Equipamento para evitar o derramamento da carga.","Requisitos fixados pelo Contran."]'::jsonb, '["Requisitos variam conforme a natureza da carga."]'::jsonb, 'O caminhão de areia usa lona para evitar o derramamento.', '["Assertiva que dispensa a proteção da carga em trajetos curtos erra."]'::jsonb, '[]'::jsonb, '["Art. 235"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-102' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3ebad7442b083142f8aba8e201de473d2081fc371fd6e4691504c99bda065319'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O veículo só pode transitar pela via quando atendidos os requisitos e condições de segurança do Código e das normas do Contran. Fabricantes, importadores, montadores e encarroçadores emitem certificado de segurança, indispensável ao cadastramento no Renavam, e devem manter disponíveis os resultados dos testes e ensaios de segurança veicular. O Contran pode autorizar, em caráter experimental e por período prefixado, a circulação em condições não previstas.', '["Requisitos de segurança do Código e do Contran.","Certificado de segurança para o Renavam.","Autorização experimental pelo Contran."]'::jsonb, '["Certificado de segurança é indispensável ao cadastro no Renavam."]'::jsonb, 'O fabricante emite o certificado de segurança antes do cadastro do veículo.', '["Assertiva que dispensa o certificado de segurança para o cadastro no Renavam erra."]'::jsonb, '[{"termo":"Renavam","significado":"Registro Nacional de Veículos Automotores."}]'::jsonb, '["Art. 105"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-103' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'be131b06a67b13f6c769ca0e397cca45c12c5b2bdf43cafa89a4f9de31d1bd7d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos em circulação têm suas condições de segurança, de controle de emissão de gases poluentes e de ruído avaliadas mediante inspeção obrigatória, na forma e periodicidade fixadas pelo Contran para segurança e pelo Conama para poluentes e ruído. Aplica-se a medida administrativa de retenção aos veículos reprovados. Ficam isentos, por três anos a partir do primeiro licenciamento, os veículos novos de categoria particular com capacidade de até sete passageiros; para os demais veículos novos, o período é de dois anos, desde que mantenham as características originais e não se envolvam em sinistro com danos de média ou grande monta.', '["Inspeção de segurança, emissões e ruído.","Retenção de veículos reprovados.","Isenção de três anos para particulares novos de até sete passageiros.","Isenção de dois anos para os demais novos."]'::jsonb, '["Isenção: três anos (particulares, até sete passageiros) e dois anos (demais)."]'::jsonb, 'O carro particular novo fica isento da inspeção nos três primeiros anos.', '["Assertiva que fixa isenção de cinco anos para veículos novos erra: são três ou dois anos, conforme o caso."]'::jsonb, '[]'::jsonb, '["Art. 131"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-104' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd527b4da37d8227243f792436e418bb3f7ea5d5fd4ee8ddc77b3775c55d8ff07'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São equipamentos obrigatórios dos veículos, entre outros a serem estabelecidos pelo Contran: cinto de segurança (salvo transporte em pé); equipamento registrador instantâneo inalterável de velocidade e tempo para veículos de transporte e condução escolar, de passageiros com mais de dez lugares e de carga com peso bruto total superior a quatro mil, quinhentos e trinta e seis quilogramas; encosto de cabeça; dispositivo de controle de emissão de gases e ruído; para bicicletas, campainha, sinalização noturna e espelho retrovisor esquerdo; air bag frontal; e luzes de rodagem diurna. Nenhum veículo pode transitar com equipamento ou acessório proibido.', '["Cinto, encosto de cabeça, registrador, air bag e luzes diurnas.","Equipamentos obrigatórios das bicicletas.","Vedado equipamento ou acessório proibido."]'::jsonb, '["Rol não exaustivo: o Contran pode acrescentar equipamentos.","ATUALIZAÇÃO: o inciso das luzes de rodagem diurna foi incluído por lei posterior."]'::jsonb, 'A bicicleta deve ter campainha e sinalização noturna.', '["Assertiva que dispensa o espelho retrovisor esquerdo nas bicicletas erra."]'::jsonb, '[]'::jsonb, '["Art. 230"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-105' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f34c76ba1ddc95c56b077c7deb7f097301e17c8a62392e44bd7df08d7e6a8f4e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na fabricação artesanal, na modificação do veículo ou na substituição de equipamento de segurança especificado pelo fabricante, exige-se, para licenciamento e registro, certificado de segurança expedido por instituição técnica credenciada por órgão de metrologia legal, conforme norma do Contran. Para blindagem de veículo, não se exige qualquer outro documento ou autorização para o registro ou o licenciamento.', '["Certificado de segurança de instituição credenciada.","Blindagem não exige outra autorização."]'::jsonb, '["Blindagem: nenhum outro documento ou autorização."]'::jsonb, 'O veículo modificado só é licenciado com o certificado de segurança.', '["Assertiva que dispensa o certificado de segurança em veículos de fabricação artesanal erra."]'::jsonb, '[]'::jsonb, '["Art. 98"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-106' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0da33f25d29efe73c97f67349726586ddafeb87a77b4544fe94dc414109d1ff4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos de aluguel, destinados ao transporte individual ou coletivo de passageiros, devem satisfazer, além das exigências do Código, às condições técnicas e aos requisitos de segurança, higiene e conforto estabelecidos pelo poder competente para autorizar, permitir ou conceder a exploração da atividade.', '["Exigências do Código e do poder concedente.","Segurança, higiene e conforto."]'::jsonb, '["O poder concedente define requisitos adicionais."]'::jsonb, 'O táxi cumpre as exigências do município, além do Código.', '["Assertiva que afasta as exigências do poder concedente do veículo de aluguel erra."]'::jsonb, '[]'::jsonb, '["Art. 135"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-107' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '125b0bdccce5e4f651412f6115f18880713b19104305c93e49bad1265eca7e36'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Onde não houver linha regular de ônibus, a autoridade com circunscrição sobre a via pode autorizar, a título precário, o transporte de passageiros em veículo de carga ou misto, atendidas as condições de segurança. Essa autorização não pode exceder a doze meses, prazo a partir do qual a autoridade deve implantar o serviço regular de transporte coletivo.', '["Transporte excepcional em veículo de carga ou misto.","Autorização precária.","Prazo máximo de doze meses."]'::jsonb, '["Máximo de doze meses."]'::jsonb, 'Em região sem ônibus, autoriza-se temporariamente o transporte em veículo misto.', '["Assertiva que fixa em vinte e quatro meses o prazo da autorização precária erra: são doze meses."]'::jsonb, '[]'::jsonb, '["Art. 109"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-108' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2bd196ca87db144501a1b039d2e77538bd27277dbaf71c8ab0349b6180722c90'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O transporte de carga em veículos destinados ao transporte de passageiros só pode ser realizado de acordo com as normas estabelecidas pelo Contran.', '["Carga em veículo de passageiros só conforme o Contran."]'::jsonb, '["Depende das normas do Contran."]'::jsonb, 'O ônibus só carrega encomendas nos termos da norma do Contran.', '["Assertiva que permite carga livre em veículos de passageiros erra."]'::jsonb, '[]'::jsonb, '["Art. 108"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-109' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '682694f152ebf25ad9c3bcff4b80a50e82a5ce53d23d28510a4ad55a93ae517c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O veículo que tiver alterada qualquer de suas características para competição ou finalidade análoga só pode circular nas vias públicas com licença especial da autoridade de trânsito, em itinerário e horário fixados.', '["Licença especial da autoridade de trânsito.","Itinerário e horário fixados."]'::jsonb, '["Licença especial, com itinerário e horário."]'::jsonb, 'O carro de competição só circula na via com licença e rota definidas.', '["Assertiva que dispensa licença para circular com veículo modificado para competição erra."]'::jsonb, '[]'::jsonb, '["Art. 98"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-110' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3d25a98c7c863c7b40f0dbfb737f3c5889550485ce0f166e781c755f2c3cdf61'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedado, nas áreas envidraçadas do veículo, o uso de cortinas, persianas fechadas ou similares em veículos em movimento, salvo nos que possuam espelhos retrovisores em ambos os lados, e a aposição de inscrições, películas, painéis decorativos ou pinturas quando comprometer a segurança do veículo, na forma da regulamentação do Contran. É proibida a inscrição de caráter publicitário ou outra que desvie a atenção dos condutores em toda a extensão do para-brisa e da traseira, salvo se não colocar em risco a segurança.', '["Vedadas cortinas e persianas fechadas, com exceção.","Películas e pinturas que comprometam a segurança.","Vedada publicidade que desvie a atenção."]'::jsonb, '["ATUALIZAÇÃO: o inciso I (películas) foi suprimido; a regulação cabe ao Contran."]'::jsonb, 'Persiana fechada no vidro traseiro só é permitida com espelhos retrovisores dos dois lados.', '["Assertiva que permite persianas fechadas em qualquer veículo erra."]'::jsonb, '[]'::jsonb, '["Art. 230"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-111' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '91d35962c9658271aba716ca935c23fb91f8ed8cbd742367760efd7a910bd6d9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os importadores, as montadoras, as encarroçadoras e os fabricantes de veículos e autopeças são responsáveis civil e criminalmente por danos causados aos usuários, a terceiros e ao meio ambiente, decorrentes de falhas oriundas de projetos e da qualidade dos materiais e equipamentos utilizados na fabricação.', '["Responsabilidade civil e criminal.","Danos a usuários, terceiros e ao meio ambiente."]'::jsonb, '["Responsabilidade CIVIL E CRIMINAL."]'::jsonb, 'A montadora responde por falha de projeto que causou acidente.', '["Assertiva que limita a responsabilidade dos fabricantes à esfera civil erra."]'::jsonb, '[]'::jsonb, '["Art. 103"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-113' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '81268cea54958cec0ef92b543ea8bdd7c2d1dfd5ddc28004e6647eb6aca506a9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O veículo é identificado obrigatoriamente por caracteres gravados no chassi ou monobloco, reproduzidos em outras partes, conforme o Contran. A gravação é feita pelo fabricante ou montador e identifica o veículo, seu fabricante, suas características e o ano de fabricação, que não pode ser alterado. As regravações dependem de prévia autorização da autoridade executiva de trânsito e só são processadas por estabelecimento credenciado, mediante comprovação de propriedade. Nenhum proprietário pode modificar a identificação sem prévia permissão.', '["Gravação no chassi ou monobloco.","Ano de fabricação inalterável.","Regravação com autorização e por estabelecimento credenciado."]'::jsonb, '["O ano de fabricação NÃO pode ser alterado."]'::jsonb, 'A regravação do chassi só é feita por oficina credenciada, com autorização.', '["Assertiva que permite alterar o ano de fabricação na regravação erra."]'::jsonb, '[]'::jsonb, '["Art. 115"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-114' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '98b7abf94abba1a2e8471471b6c5f1fdf8870e8afcc322311424c6209ccd1c4d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O veículo é identificado externamente por placas dianteira e traseira, esta lacrada em sua estrutura, segundo as especificações do Contran. Os caracteres são individualizados para cada veículo e o acompanham até a baixa do registro, vedado o reaproveitamento. As placas verde e amarela da Bandeira Nacional são de uso exclusivo dos veículos de representação pessoal de autoridades como o Presidente da República, ministros do Supremo e Ministros de Estado. Veículos de duas ou três rodas são dispensados da placa dianteira. Aparelhos automotores para trabalhos de construção ou pavimentação estão sujeitos ao registro, dispensados licenciamento e emplacamento.', '["Placas dianteira e traseira, esta lacrada.","Caracteres individualizados e sem reaproveitamento.","Placas verde e amarela restritas a altas autoridades.","Veículos de duas ou três rodas dispensados da placa dianteira."]'::jsonb, '["Motos e triciclos usam só a placa traseira.","Placa lacrada na estrutura do veículo."]'::jsonb, 'A motocicleta circula apenas com a placa traseira.', '["Assertiva que exige placa dianteira nas motocicletas erra."]'::jsonb, '[]'::jsonb, '["Art. 116"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-115' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4a433cc17f52983394dae3305872c66736664b2fbcbfe5e3f03811b2c3351379'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos de propriedade da União, dos Estados e do Distrito Federal, devidamente registrados e licenciados, ou aqueles sob posse dos órgãos de segurança pública, somente quando estritamente usados em serviço reservado de caráter policial, podem usar placas particulares, obedecidos os critérios da legislação sobre veículo oficial. As placas são concedidas mediante solicitação aos órgãos executivos de trânsito dos Estados e do Distrito Federal e vinculadas ao órgão de segurança pública solicitante.', '["Placas particulares em serviço reservado de caráter policial.","Concessão pelos órgãos executivos estaduais e distritais.","Vinculação ao órgão solicitante."]'::jsonb, '["Só em serviço RESERVADO de caráter policial."]'::jsonb, 'A viatura descaracterizada em operação reservada usa placa particular.', '["Assertiva que permite placa particular a qualquer veículo oficial em qualquer serviço erra."]'::jsonb, '[]'::jsonb, '["Art. 115"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-116' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd7a3a12bf9346932c5de6eeca1c4f292533b720cbdbb3e4b23fb6b78b921f5ae'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos de transporte de carga e os coletivos de passageiros devem conter, em local facilmente visível, a inscrição indicativa de sua tara, do peso bruto total, do peso bruto total combinado ou capacidade máxima de tração e de sua lotação, vedado o uso em desacordo com sua classificação.', '["Inscrição de tara, PBT, PBTC ou CMT e lotação.","Em local facilmente visível."]'::jsonb, '["Vedado usar o veículo em desacordo com a classificação."]'::jsonb, 'O caminhão traz a tara e o peso bruto total inscritos.', '["Assertiva que dispensa a inscrição da lotação nos coletivos erra."]'::jsonb, '[]'::jsonb, '["Art. 100"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-117' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f1902cadae077d68f68000e3cfc1eead48bcb48260f84c60c367af1af45994ac'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A circulação de veículo no território nacional, independentemente de sua origem, em trânsito entre o Brasil e países com os quais exista acordo ou tratado internacional, reger-se-á pelas disposições do Código e pelas convenções e acordos internacionais ratificados.', '["Aplicação do Código e dos tratados ratificados."]'::jsonb, '["Convenções internacionais ratificadas também se aplicam."]'::jsonb, 'O veículo de outro país do Mercosul segue o Código e o acordo ratificado.', '["Assertiva que afasta o Código para veículos estrangeiros em trânsito erra."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-118' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4b28aa3648983dae6f385c670472a2b9e56c9c28834e4ac72d3d9a47ea384ccc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As repartições aduaneiras e os órgãos de controle de fronteira comunicam diretamente ao Renavam a entrada e a saída temporária ou definitiva de veículos. Os veículos licenciados no exterior não podem sair do território nacional sem o prévio pagamento ou depósito dos valores das infrações de trânsito e do ressarcimento de danos que tiverem causado ao patrimônio público ou de particulares. Os que saírem sem esse cumprimento e forem flagrados tentando ingressar ou em circulação no território nacional são retidos até a regularização.', '["Comunicação ao Renavam.","Saída condicionada ao pagamento das infrações e danos.","Retenção em caso de nova entrada sem regularização."]'::jsonb, '["Saída do veículo estrangeiro só após pagar ou depositar infrações e danos."]'::jsonb, 'O turista paga as multas antes de deixar o país com o carro.', '["Assertiva que permite a saída do veículo estrangeiro com multas pendentes erra."]'::jsonb, '[]'::jsonb, '["Art. 118"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-119' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '93eae11f6c2ce0b02dbe82cccc89132d209f13360055207bc8bc61d199772b8b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todo veículo automotor, articulado, reboque ou semirreboque deve ser registrado perante o órgão executivo de trânsito do Estado ou do Distrito Federal, no Município de domicílio ou residência de seu proprietário. Veículos oficiais da administração direta de qualquer poder são registrados com indicação expressa, por pintura nas portas, do nome, sigla ou logotipo do órgão, excetuados os de representação e os do art. 116. A regra não se aplica ao veículo de uso bélico.', '["Registro no órgão estadual ou distrital.","Município de domicílio do proprietário.","Identificação pintada nos veículos oficiais."]'::jsonb, '["Veículos oficiais: identificação pintada nas portas."]'::jsonb, 'O proprietário registra o carro no Detran do seu estado de domicílio.', '["Assertiva que manda registrar o veículo no órgão federal erra: é o órgão estadual ou distrital."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-120' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0f3f06bfbdeff75aaa960bfab6fa9d2924ee72dbcee9f784e8b1722ac53988c6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Registrado o veículo, expede-se o Certificado de Registro de Veículo (CRV), em meio físico ou digital, à escolha do proprietário, conforme os modelos e especificações do Contran, com características de invulnerabilidade à falsificação e à adulteração.', '["CRV em meio físico ou digital.","Escolha do proprietário.","Invulnerabilidade à falsificação."]'::jsonb, '["ATUALIZAÇÃO: a opção pelo meio digital veio de lei posterior."]'::jsonb, 'O proprietário escolhe receber o CRV em formato digital.', '["Assertiva que obriga o CRV físico erra: o proprietário pode optar pelo digital."]'::jsonb, '[{"termo":"CRV","significado":"Certificado de Registro de Veículo."}]'::jsonb, '["Art. 122"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-121' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '71bdec44babefb88a46abbef412e86bcdcf966b73fcd0f73ce3cedbadae49124'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a expedição do CRV, o órgão executivo de trânsito consulta o cadastro do Renavam e exige do proprietário a nota fiscal fornecida pelo fabricante ou revendedor, ou documento equivalente expedido por autoridade competente, e, em veículo importado por membro de missões diplomáticas ou organismos internacionais, o documento do Ministério das Relações Exteriores.', '["Consulta ao Renavam.","Nota fiscal ou documento equivalente.","Documento do Itamaraty para diplomatas."]'::jsonb, '["Primeiro registro exige nota fiscal."]'::jsonb, 'A concessionária entrega a nota fiscal para o primeiro registro.', '["Assertiva que dispensa a nota fiscal para o primeiro registro erra."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-122' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '246063bba786c941cab2d48643884db7eb403e56aa7228d103711ef1375b2867'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigatória a expedição de novo CRV quando for transferida a propriedade, o proprietário mudar o Município de domicílio ou residência, for alterada qualquer característica do veículo ou houver mudança de categoria. Na transferência de propriedade, o prazo para as providências é de trinta dias; nos demais casos, as providências são imediatas. A mudança de endereço no mesmo Município é comunicada em trinta dias. A transferência pode ser feita integralmente por meio eletrônico, com assinaturas eletrônicas qualificadas ou avançadas, nos termos da regulamentação.', '["Quatro hipóteses de novo CRV.","Trinta dias na transferência de propriedade.","Trinta dias para comunicar mudança de endereço no mesmo Município.","Transferência eletrônica."]'::jsonb, '["Transferência de propriedade: TRINTA dias.","ATUALIZAÇÃO: transferência totalmente eletrônica prevista por lei posterior."]'::jsonb, 'O comprador tem trinta dias para transferir o veículo para o seu nome.', '["Assertiva que fixa em sessenta dias o prazo do comprador para a transferência erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 134"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-123' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b3599565a4661b30b279f35bdb82151bb3051aaa46e3d5bb515e7aa34f2c3bcb'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a expedição do novo CRV são exigidos, entre outros, o CRV anterior, o Certificado de Licenciamento Anual, o comprovante de transferência de propriedade quando for o caso, o certificado de segurança veicular e de emissão de poluentes e ruído em caso de adaptação ou alteração, o comprovante de procedência dos componentes e agregados adaptados, a autorização do Ministério das Relações Exteriores para veículo de missão diplomática, e a certidão negativa de roubo ou furto.', '["CRV anterior e licenciamento anual.","Comprovante de transferência.","Certificados e comprovantes de adaptações.","Documentos específicos para casos especiais."]'::jsonb, '["Rol de documentos exigíveis para o novo CRV."]'::jsonb, 'Na venda do carro, apresentam-se o CRV anterior e o comprovante de transferência.', '["Assertiva que dispensa o licenciamento anual para expedir novo CRV erra."]'::jsonb, '[]'::jsonb, '["Art. 123"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-124' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd8367dfdd65ebcf689d5d514ca97fd0ea376ef62cfb494d8b49ed0ae9bdc09f5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As informações sobre o chassi, o monobloco, os agregados e as características originais do veículo devem ser prestadas ao Renavam pelo fabricante ou montadora antes da comercialização, no caso de veículo nacional; pelo órgão alfandegário, no caso de veículo importado por pessoa física; e pelo importador, no caso de importado por pessoa jurídica. As informações são repassadas ao órgão responsável pelo registro, que comunica ao Renavam quando o veículo for registrado.', '["Fabricante: veículo nacional.","Órgão alfandegário: importado por pessoa física.","Importador: importado por pessoa jurídica."]'::jsonb, '["Quem informa depende da origem e do importador."]'::jsonb, 'A montadora cadastra o veículo no Renavam antes de vendê-lo.', '["Assertiva que atribui ao proprietário a prestação das informações originais ao Renavam erra."]'::jsonb, '[]'::jsonb, '["Art. 103"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-125' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4da577ebf7ef8d22785c6c9acc15de72760a61eed34f466ee4c2493113d61b82'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O proprietário de veículo irrecuperável ou destinado à desmontagem deve requerer a baixa do registro, no prazo e forma do Contran, vedada a remontagem sobre o mesmo chassi de modo a manter o registro anterior. A obrigação é da seguradora ou do adquirente do veículo destinado à desmontagem, quando sucederem ao proprietário. A existência de débitos fiscais ou multas de trânsito e ambientais não impede a baixa do registro.', '["Baixa do registro de veículo irrecuperável.","Obrigação da seguradora ou adquirente, quando sucessores.","Débitos não impedem a baixa."]'::jsonb, '["Débitos e multas NÃO impedem a baixa do registro."]'::jsonb, 'O veículo sinistrado em perda total tem o registro baixado pela seguradora.', '["Assertiva que condiciona a baixa do registro à quitação de multas erra."]'::jsonb, '[]'::jsonb, '["Art. 127"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-126' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cfc55c3ee11ddeb78bdd8b682466b1650d1b49247f7e020c6403d6265791d3c2'
