insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O registro dos tratores e demais aparelhos automotores destinados a puxar ou arrastar maquinaria agrícola ou a executar trabalhos agrícolas é efetuado, sem ônus, pelo Ministério da Agricultura e Pecuária, diretamente ou mediante convênio.', '["Registro pelo Ministério da Agricultura e Pecuária.","Sem ônus."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Sem cobrança de taxas."]'::jsonb, 'O trator agrícola é registrado no cadastro do Ministério da Agricultura.', '["Assertiva que atribui ao Detran o registro de tratores agrícolas erra."]'::jsonb, '[]'::jsonb, '["Art. 115"]'::jsonb, 'under_review', 'claude'
