insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todo veículo automotor, articulado, reboque ou semirreboque, para transitar na via, deve ser licenciado anualmente pelo órgão executivo de trânsito do Estado ou do Distrito Federal onde estiver registrado. A regra não se aplica a veículo de uso bélico. No caso de transferência de residência ou domicílio, vale durante o exercício o licenciamento de origem.', '["Licenciamento anual.","Órgão estadual ou distrital do registro.","Licenciamento de origem vale no exercício em caso de mudança."]'::jsonb, '["Anual e no órgão onde o veículo está registrado."]'::jsonb, 'O proprietário licencia o veículo todos os anos no Detran de registro.', '["Assertiva que torna o licenciamento bienal erra: é anual."]'::jsonb, '[]'::jsonb, '["Art. 131"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-130' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '91d96cd76ed8cd99bf8d29eabfc52cb2ea2d96314fb70a1ca82b0311481384b9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
