insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Certificado de Licenciamento Anual (CRLV) é expedido ao veículo licenciado, vinculado ao CRV, em meio físico ou digital, à escolha do proprietário. O primeiro licenciamento é feito simultaneamente ao registro. O veículo só é considerado licenciado estando quitados os débitos de tributos, encargos e multas de trânsito e ambientais vinculados a ele, independentemente da responsabilidade pelas infrações. Ao licenciar, o proprietário comprova aprovação nas inspeções de segurança e de emissões. As campanhas de chamamento (recall) não atendidas em um ano passam a constar do CRLV, e o licenciamento exige o atendimento a elas.', '["CRLV vinculado ao CRV, físico ou digital.","Primeiro licenciamento junto com o registro.","Débitos quitados para considerar o veículo licenciado.","Inspeções e recall."]'::jsonb, '["ATUALIZAÇÃO: regras sobre recall incluídas por lei posterior.","Licenciado = débitos quitados."]'::jsonb, 'O veículo com multa em aberto não é considerado licenciado.', '["Assertiva que considera licenciado o veículo com multas em aberto erra."]'::jsonb, '[{"termo":"CRLV","significado":"Certificado de Registro e Licenciamento de Veículo, o licenciamento anual."}]'::jsonb, '["Art. 130"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-131' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b7c5c7ef414169abac2931a32f576ff6e877fc908877e7c105f0523d6b7f2904'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos novos não estão sujeitos ao licenciamento e têm sua circulação regulada pelo Contran durante o trajeto entre a fábrica e o Município de destino. O mesmo se aplica aos veículos importados, durante o trajeto entre a alfândega ou entreposto e o Município de destino.', '["Veículos novos dispensados de licenciamento no trajeto.","Circulação regulada pelo Contran.","Vale para importados do alfândega ao destino."]'::jsonb, '["Dispensa apenas no trajeto fábrica ou alfândega até o destino."]'::jsonb, 'O caminhão cegonha leva veículos novos da fábrica à concessionária.', '["Assertiva que isenta o veículo novo de licenciamento por tempo indeterminado erra."]'::jsonb, '[]'::jsonb, '["Art. 130"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-132' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f78e3414effc292ad537c8f4694cb57f5b74b28184fdc8ec6696dd08d3fede39'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigatório o porte do Certificado de Licenciamento Anual. O porte é dispensado quando, no momento da fiscalização, for possível ter acesso ao sistema informatizado para verificar se o veículo está licenciado.', '["Porte obrigatório do CRLV.","Dispensa se o sistema permitir a verificação."]'::jsonb, '["ATUALIZAÇÃO: a dispensa do porte veio de lei posterior."]'::jsonb, 'O agente consulta o sistema e dispensa a apresentação do documento.', '["Assertiva que exige o porte do documento mesmo havendo consulta ao sistema erra."]'::jsonb, '[]'::jsonb, '["Art. 131"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-133' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1910ac45eb4ea70bb70f5654c94bccb1f1ad0152a2c5d09cb72d82053ff88929'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na transferência de propriedade, expirado o prazo de trinta dias sem que o novo proprietário tenha tomado as providências, o antigo proprietário deve encaminhar ao órgão executivo de trânsito, em sessenta dias, cópia autenticada do comprovante de transferência, devidamente assinado e datado, sob pena de responder solidariamente pelas penalidades impostas e suas reincidências até a data da comunicação. O comprovante pode ser substituído por documento eletrônico com assinatura eletrônica válida.', '["Prazo de sessenta dias para o antigo proprietário.","Responsabilidade solidária até a comunicação.","Documento eletrônico admitido."]'::jsonb, '["Sessenta dias, após vencido o prazo do novo proprietário."]'::jsonb, 'O vendedor comunica a venda ao Detran para não responder por multas futuras.', '["Assertiva que isenta o antigo proprietário de qualquer comunicação erra."]'::jsonb, '[]'::jsonb, '["Art. 123"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-134' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '04fb4fda7e03ecb2217d63ee92b68d9a29478097af8ec71080e15e938931ac05'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
