insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran especifica as bicicletas motorizadas e equiparados não sujeitos ao registro, ao licenciamento e ao emplacamento para circulação nas vias.', '["Especificação pelo Contran."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'A bicicleta elétrica dentro dos limites do Contran circula sem registro.', '["Assertiva que exige emplacamento de toda bicicleta motorizada erra."]'::jsonb, '[]'::jsonb, '["Art. 115"]'::jsonb, 'under_review', 'claude'
