insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos de aluguel, destinados ao transporte individual ou coletivo de passageiros de linhas regulares ou empregados em qualquer serviço remunerado, para registro, licenciamento e emplacamento de característica comercial, devem estar devidamente autorizados pelo poder público concedente.', '["Autorização do poder concedente.","Emplacamento de característica comercial."]'::jsonb, '["Sem autorização do poder concedente, sem placa comercial."]'::jsonb, 'O táxi obtém a autorização da prefeitura antes do emplacamento comercial.', '["Assertiva que dispensa a autorização do poder concedente para veículos de aluguel erra."]'::jsonb, '[]'::jsonb, '["Art. 107"]'::jsonb, 'under_review', 'claude'
