insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos de condução coletiva de escolares só podem circular com autorização do órgão executivo de trânsito estadual ou distrital, exigindo-se registro como veículo de passageiros; inspeção semestral; pintura de faixa horizontal amarela de quarenta centímetros de largura, à meia altura, com o dístico ESCOLAR em preto; registrador instantâneo inalterável de velocidade e tempo; lanternas de luz branca, fosca ou amarela na parte dianteira e vermelha na traseira; cintos de segurança em número igual à lotação; e outros requisitos do Contran.', '["Autorização do órgão estadual ou distrital.","Inspeção semestral.","Faixa amarela de quarenta centímetros com o dístico ESCOLAR.","Registrador, lanternas e cintos."]'::jsonb, '["Inspeção SEMESTRAL e faixa amarela de QUARENTA centímetros."]'::jsonb, 'A van escolar tem a faixa amarela com ESCOLAR e passa por inspeção a cada semestre.', '["Assertiva que fixa inspeção anual para o veículo escolar erra: é semestral."]'::jsonb, '[]'::jsonb, '["Art. 138"]'::jsonb, 'under_review', 'claude'
