insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autorização do veículo escolar deve ser afixada na parte interna do veículo, em local visível, com inscrição da lotação permitida, sendo vedada a condução de escolares em número superior à capacidade estabelecida pelo fabricante.', '["Autorização afixada em local visível.","Lotação inscrita.","Vedado exceder a capacidade."]'::jsonb, '["Lotação do fabricante é o limite."]'::jsonb, 'A van escolar exibe a autorização e a lotação dentro do veículo.', '["Assertiva que permite exceder a capacidade do fabricante com crianças pequenas erra."]'::jsonb, '[]'::jsonb, '["Art. 136"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-137' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'efba6908acc4c4a10eaed61578451196440120e69dbcf395d13d809e81576114'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor de veículo destinado à condução de escolares deve ter idade superior a vinte e um anos, ser habilitado na categoria D, não ter cometido mais de uma infração gravíssima nos últimos doze meses e ser aprovado em curso especializado, nos termos da regulamentação do Contran.', '["Idade superior a vinte e um anos.","Categoria D.","No máximo uma infração gravíssima em doze meses.","Curso especializado."]'::jsonb, '["Mais de VINTE E UM anos e categoria D."]'::jsonb, 'O motorista de ônibus escolar tem 25 anos, categoria D e curso especializado.', '["Assertiva que exige apenas a categoria B para conduzir escolares erra: é categoria D."]'::jsonb, '[]'::jsonb, '["Art. 145"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-138' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '842a4eff9282016312e8c445f8e6089b32efe87ef4c2ec981420a9e1fe0ef5d2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As regras do capítulo sobre condução de escolares não excluem a competência municipal de aplicar as exigências previstas em seus regulamentos para o transporte de escolares.', '["Municípios podem fazer exigências adicionais."]'::jsonb, '["Competência municipal complementar."]'::jsonb, 'A prefeitura exige vistoria extra para vans escolares.', '["Assertiva que impede o município de regulamentar o transporte escolar erra."]'::jsonb, '[]'::jsonb, '["Art. 136"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-139' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'dfea727d06728ac39bfc639dcfbca4f5d9705bd365b6e5576493e739e74f0f22'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As motocicletas e motonetas destinadas ao transporte remunerado de mercadorias, o moto-frete, só podem circular com autorização do órgão executivo de trânsito estadual ou distrital, exigindo-se, entre outros requisitos, protetor de motor (mata-cachorro), aparador de linha (antena corta-pipas), nos termos do Contran, e inspeção semestral para verificação dos equipamentos obrigatórios e de segurança. É proibido o transporte de combustíveis, produtos inflamáveis ou tóxicos e de galões, com exceção do gás de cozinha e de galões de água mineral, com o auxílio de side-car.', '["Autorização do órgão estadual ou distrital.","Mata-cachorro e antena corta-pipas.","Inspeção semestral.","Vedado transporte de combustíveis e inflamáveis."]'::jsonb, '["ATUALIZAÇÃO: o inciso sobre registro como categoria de aluguel tem vigência encerrada.","Exceção: gás de cozinha e galões de água mineral, com side-car."]'::jsonb, 'O motofretista instala a antena corta-pipas e passa pela inspeção semestral.', '["Assertiva que permite o transporte de combustíveis em moto-frete erra."]'::jsonb, '[]'::jsonb, '["Art. 139-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-139-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '43b110f90e8f349e397bb982ba9a474a443bd6d77b9d01ebac434d00c9c45f9d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As regras do capítulo sobre moto-frete não excluem a competência municipal ou estadual de aplicar as exigências previstas em seus regulamentos para a atividade no âmbito de suas circunscrições.', '["Competência municipal ou estadual complementar."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O município exige credenciamento adicional dos motofretistas.', '["Assertiva que impede estados e municípios de regular o moto-frete erra."]'::jsonb, '[]'::jsonb, '["Art. 139-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-139-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c25e9f1f2fda37ba4ed769b6667f54fd399cd116240bffe58cf10bc623790244'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
